c='p2';B='AI 3'
def box(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{f}" stroke="{s}" stroke-width="3"/><text x="{x+w/2}" y="{y+h/2+7}" text-anchor="middle" font-size="{fs}" font-weight="800" fill="#0B2545" font-family="sans-serif">{t}</text>'
def svg(h,b): return f'<svg viewBox="0 0 520 {h}" style="width:100%">{b}</svg>'
S=[]
S.append(TITLE('TIN HỌC · TRÍ TUỆ NHÂN TẠO 3','ĐÁNH GIÁ MÔ HÌNH<br>VÀ HIỆN TƯỢNG QUÁ KHỚP','Chia dữ liệu huấn luyện – kiểm tra, độ chính xác, ma trận nhầm lẫn, precision, recall, quá khớp, dưới khớp.',['huấn luyện – kiểm tra','độ chính xác','ma trận nhầm lẫn','quá khớp','recall']))
S.append(goals(c,B,['Giải thích vì sao phải <b>chia dữ liệu</b> huấn luyện – kiểm tra.','Tính <b>độ chính xác</b>, <b>precision</b>, <b>recall</b> từ <b>ma trận nhầm lẫn</b>.','Nhận biết <b>quá khớp</b> và <b>dưới khớp</b>.','Nêu cách <b>hạn chế quá khớp</b>.','Giải bài tập đánh giá mô hình kiểu HSG.'],['Chia dữ liệu','Độ chính xác','Ma trận nhầm lẫn','Quá khớp','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Vì sao phải đánh giá?',card('Mục đích',ul(['Biết mô hình <b>dự đoán tốt đến đâu</b> với dữ liệu <b>chưa từng thấy</b>.','Đánh giá trên chính dữ liệu đã học sẽ cho kết quả <b>quá lạc quan</b>.'],6)),KEY('Ví dụ: học sinh <b>học thuộc đáp án</b> đề cũ thì đạt điểm tối đa đề cũ nhưng <b>chưa chắc làm được đề mới</b>.')))
S.append(S2(c,B+' · 1','Chia dữ liệu: huấn luyện và kiểm tra',RES(svg(150,box(10,40,330,70,'Tập huấn luyện (70–80%)','#BBDEFB','#1565C0',22)+box(340,40,170,70,'Kiểm tra (20–30%)','#FFCCBC','#D84315',20)),'Chia dữ liệu'),card('Quy tắc',ul(['<b>Huấn luyện</b>: để mô hình học.','<b>Kiểm tra</b>: chỉ dùng để <b>đánh giá cuối</b>.','<b>Xáo trộn</b> dữ liệu trước khi chia.'],6))))
S.append(S2(c,B+' · 1','Ba tập: huấn luyện, kiểm định, kiểm tra',T(tr('Tập','Dùng để','Tỉ lệ thường gặp',h=True)+tr('<b>Huấn luyện</b>','học tham số mô hình','60–70%')+tr('<b>Kiểm định</b> (validation)','chọn siêu tham số (ví dụ k)','15–20%')+tr('<b>Kiểm tra</b> (test)','đánh giá cuối cùng','15–20%')),KEY('Tập kiểm tra phải <b>giữ kín</b> đến cuối; dùng nó để chọn mô hình thì kết quả không còn khách quan (<b>rò rỉ dữ liệu</b>).')))
S.append(PYR(c,B+' · 1','Chia dữ liệu bằng Python','import random\nrandom.seed(1)\ndata = list(range(10))\nrandom.shuffle(data)\nn = int(0.8 * len(data))\ntrain, test = data[:n], data[n:]\nprint(train)\nprint(test)\nprint(len(train), len(test))',KEY('<b>shuffle</b> xáo trộn, rồi cắt 80% / 20%. <code>random.seed</code> giúp kết quả <b>lặp lại được</b>.'),21))
S.append(S2(c,B+' · 2','Độ chính xác (accuracy)',card('Công thức',ul(['<b>Accuracy = số dự đoán đúng / tổng số mẫu</b>.','Ví dụ: đúng 90/100 → 90%.'],6)),KEY('Cảnh báo <b>dữ liệu mất cân bằng</b>: 99% thư không rác; mô hình luôn đoán “không rác” đạt <b>99%</b> nhưng <b>vô dụng</b>.')+WARN('Accuracy chưa đủ, cần thêm <b>precision, recall</b>.')))
S.append(S2(c,B+' · 2','Ma trận nhầm lẫn (confusion matrix)',T(tr('','Dự đoán: Có','Dự đoán: Không',h=True)+tr('<b>Thực tế: Có</b>','<b>TP</b> (đúng dương)','<b>FN</b> (sai âm)')+tr('<b>Thực tế: Không</b>','<b>FP</b> (sai dương)','<b>TN</b> (đúng âm)')),KEY('<b>TP</b>: có và đoán có · <b>TN</b>: không và đoán không · <b>FP</b>: không mà đoán có · <b>FN</b>: có mà đoán không.')+OK('Accuracy = <b>(TP + TN) / (TP + TN + FP + FN)</b>.')))
S.append(S2(c,B+' · 2','Precision và Recall',card('Precision (độ chính xác dương)',ul(['<b>TP / (TP + FP)</b>','Trong số đoán “có”, bao nhiêu <b>đúng</b>.'],6))+card('Recall (độ phủ)',ul(['<b>TP / (TP + FN)</b>','Trong số thực sự “có”, tìm được <b>bao nhiêu</b>.'],6)),KEY('Lọc thư rác: ưu tiên <b>precision</b> (đừng chặn nhầm thư thật). Tầm soát bệnh: ưu tiên <b>recall</b> (đừng bỏ sót bệnh nhân).')))
S.append(PYR(c,B+' · 2','Tính các chỉ số bằng Python','thuc = [1,1,1,0,0,0,0,1,0,0]\ndoan = [1,1,0,0,0,1,0,1,0,0]\nTP = sum(1 for t,d in zip(thuc,doan) if t==1 and d==1)\nTN = sum(1 for t,d in zip(thuc,doan) if t==0 and d==0)\nFP = sum(1 for t,d in zip(thuc,doan) if t==0 and d==1)\nFN = sum(1 for t,d in zip(thuc,doan) if t==1 and d==0)\nprint(TP, TN, FP, FN)\nprint("acc", (TP+TN)/len(thuc))\nprint("pre", TP/(TP+FP))\nprint("rec", TP/(TP+FN))',KEY('TP=3, TN=5, FP=1, FN=1 → accuracy 0,8; precision 0,75; recall 0,75.'),17))
S.append(S2(c,B+' · 2','F1-score',card('Khái niệm',ul(['<b>F1 = 2·P·R / (P + R)</b>: trung bình điều hoà của precision và recall.','Cao khi <b>cả hai cùng cao</b>.'],6)),KEY('Với P = 0,75; R = 0,75 thì <b>F1 = 0,75</b>. Với P = 1, R = 0,1: F1 ≈ <b>0,18</b> (thấp) dù precision cao.')))
S.append(S2(c,B+' · 3','Quá khớp và dưới khớp',card('Quá khớp (overfitting)',ul(['Mô hình <b>học thuộc</b> cả nhiễu dữ liệu huấn luyện.','Sai số huấn luyện <b>rất thấp</b> nhưng kiểm tra <b>cao</b>.'],6))+card('Dưới khớp (underfitting)',ul(['Mô hình <b>quá đơn giản</b>, chưa học đủ quy luật.','Sai số <b>cao cả hai</b> tập.'],6)),KEY('Mong muốn: mô hình <b>vừa khớp</b> (tổng quát hoá tốt).')))
S.append(TB(c,B+' · 3','Nhận biết qua sai số',['Tình huống','Huấn luyện','Kiểm tra','Kết luận'],[['A','sai số <b>thấp</b>','sai số <b>thấp</b>','vừa khớp'],['B','sai số <b>thấp</b>','sai số <b>cao</b>','<b>quá khớp</b>'],['C','sai số <b>cao</b>','sai số <b>cao</b>','<b>dưới khớp</b>'],['D','sai số cao','sai số thấp','bất thường: kiểm tra lại rò rỉ dữ liệu']],note=KEY('Quá khớp = <b>khoảng cách lớn</b> giữa kết quả huấn luyện và kiểm tra.')))
S.append(S2(c,B+' · 3','Minh hoạ đường cong khớp',RES('<svg viewBox="0 0 520 260" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="20" text-anchor="middle"><rect x="2" y="2" width="166" height="200" fill="none" stroke="#0B2545" stroke-width="2"/><rect x="177" y="2" width="166" height="200" fill="none" stroke="#0B2545" stroke-width="2"/><rect x="352" y="2" width="166" height="200" fill="none" stroke="#0B2545" stroke-width="2"/><line x1="15" y1="150" x2="155" y2="60" stroke="#D84315" stroke-width="4"/><path d="M190 150 Q250 20 330 130" fill="none" stroke="#2E7D32" stroke-width="4"/><path d="M365 150 L385 60 L405 160 L425 40 L445 170 L465 50 L485 140 L505 70" fill="none" stroke="#D84315" stroke-width="4"/><g fill="#1565C0"><circle cx="35" cy="120" r="6"/><circle cx="70" cy="90" r="6"/><circle cx="100" cy="125" r="6"/><circle cx="135" cy="65" r="6"/><circle cx="210" cy="110" r="6"/><circle cx="250" cy="55" r="6"/><circle cx="290" cy="70" r="6"/><circle cx="325" cy="125" r="6"/><circle cx="385" cy="60" r="6"/><circle cx="425" cy="40" r="6"/><circle cx="465" cy="50" r="6"/><circle cx="405" cy="160" r="6"/></g><text x="85" y="235">DƯỚI KHỚP</text><text x="260" y="235" fill="#2E7D32">VỪA KHỚP</text><text x="435" y="235" fill="#D84315">QUÁ KHỚP</text></g></svg>','Ba mô hình'),card('Nhận xét',ul(['Dưới khớp: <b>đường thẳng</b> bỏ lỡ xu hướng.','Quá khớp: <b>đi qua từng điểm</b>, uốn lượn theo nhiễu.'],6))))
S.append(S2(c,B+' · 4','Nguyên nhân quá khớp',card('Thường do',ul(['Mô hình <b>quá phức tạp</b> so với lượng dữ liệu.','Dữ liệu huấn luyện <b>quá ít</b> hoặc <b>nhiễu</b>.','Huấn luyện <b>quá lâu</b>.'],6)),KEY('Ví dụ k-NN với <b>k = 1</b> luôn đúng 100% trên tập huấn luyện (mỗi điểm là láng giềng của chính nó) nhưng thường kém trên tập kiểm tra.')))
S.append(TB(c,B+' · 4','Cách hạn chế quá khớp',['Biện pháp','Giải thích'],[['<b>Thêm dữ liệu</b>','nhiều mẫu hơn → khó học thuộc nhiễu'],['<b>Đơn giản hoá</b> mô hình','giảm độ phức tạp (tăng k, giảm tầng)'],['<b>Dừng sớm</b> (early stopping)','dừng khi sai số kiểm định tăng'],['<b>Điều chuẩn</b> (regularization)','phạt mô hình phức tạp'],['<b>Kiểm định chéo</b> (cross-validation)','đánh giá nhiều lần trên các phần khác nhau'],['Làm sạch dữ liệu','bỏ nhiễu, ngoại lai']],note=KEY('Chọn mô hình đạt <b>sai số kiểm định thấp nhất</b>, không phải sai số huấn luyện thấp nhất.')))
S.append(PYR(c,B+' · 4','Quá khớp với k-NN: so sánh k','import random\nrandom.seed(0)\ndef mau(n):\n    d=[]\n    for _ in range(n):\n        x=random.random(); y=random.random()\n        nhan = 1 if x+y+random.gauss(0,0.35)>1 else 0\n        d.append(((x,y),nhan))\n    return d\ndef knn(tr,p,k):\n    ds=sorted((((p[0]-q[0])**2+(p[1]-q[1])**2),l) for q,l in tr)\n    return int(sum(l for _,l in ds[:k])*2>k)\ntr,te=mau(60),mau(60)\nfor k in (1,5,15):\n    a=sum(knn(tr,p,k)==l for p,l in tr)/len(tr)\n    b=sum(knn(tr,p,k)==l for p,l in te)/len(te)\n    print("k=",k,"train",round(a,2),"test",round(b,2))',KEY('Quan sát: <b>k = 1</b>: train rất cao, test thấp hơn nhiều (quá khớp). k lớn hơn: hai số gần nhau hơn.'),15))
S.append(S2(c,B+' · 4','Kiểm định chéo k-fold',card('Cách làm',ul(['Chia dữ liệu thành <b>K phần</b> bằng nhau.','Lần lượt dùng <b>mỗi phần làm kiểm tra</b>, K−1 phần còn lại huấn luyện.','Lấy <b>trung bình</b> K kết quả.'],6)),KEY('Ưu điểm: dùng <b>mọi mẫu</b> cho cả huấn luyện lẫn kiểm tra, đánh giá <b>ổn định</b> hơn khi dữ liệu ít.')+OK('Phổ biến: <b>K = 5</b> hoặc <b>10</b>.')))
S+=END(c,B,['Chia <b>huấn luyện</b> – <b>kiểm tra</b>; test giữ kín đến cuối.','<b>Accuracy = (TP+TN)/Tổng</b>; <b>Precision = TP/(TP+FP)</b>; <b>Recall = TP/(TP+FN)</b>.','<b>F1</b> là trung bình điều hoà của P và R.','<b>Quá khớp</b>: huấn luyện tốt, kiểm tra kém; <b>dưới khớp</b>: cả hai kém.','Giảm quá khớp: thêm dữ liệu, đơn giản hoá, dừng sớm, kiểm định chéo.'],[('Đúng trên tổng','accuracy'),('Đoán có thì đúng','precision'),('Tìm hết dương thật','recall'),('Học thuộc','quá khớp')],'Đánh giá mô hình trên chính dữ liệu huấn luyện.',['Dữ liệu <b>mất cân bằng</b> làm accuracy đánh lừa.','<b>Rò rỉ dữ liệu</b>: thông tin tập kiểm tra lọt vào huấn luyện.','Precision và recall thường <b>đánh đổi</b>.','Đường cong học: sai số theo kích thước dữ liệu.'],['<b>ROC, AUC</b>.','<b>MSE, MAE</b> cho hồi quy.','<b>Bias – variance</b> trade-off.'],
 [('Vì sao cần tập kiểm tra riêng?',),('Công thức tính accuracy từ TP, TN, FP, FN.',),('Quá khớp là gì?',),('Precision cho biết điều gì?',),('Nêu hai cách hạn chế quá khớp.',)],
 [('Đánh giá khách quan trên dữ liệu chưa từng thấy.',),('(TP + TN) / (TP + TN + FP + FN).',),('Mô hình học thuộc nhiễu: tốt trên huấn luyện, kém trên kiểm tra.',),('Trong các mẫu được đoán dương, bao nhiêu phần đúng.',),('Thêm dữ liệu; đơn giản hoá mô hình (hoặc dừng sớm).',)],
 [('Mô hình: TP=40, FP=10, FN=20, TN=30. Tính accuracy, precision, recall.',),('Mô hình đoán “không rác” cho 100 thư, trong đó 98 thật sự không rác. Accuracy? Có nên tin?',),('Mô hình A: huấn luyện 99%, kiểm tra 70%. Mô hình B: 85% và 83%. Chọn mô hình nào? Vì sao?',),('Đúng hay sai: (a) Dùng tập kiểm tra để chọn k là đúng chuẩn. (b) Recall cao nghĩa là ít bỏ sót. (c) Dưới khớp thường do mô hình quá phức tạp. (d) 5-fold cho 5 kết quả đánh giá.',),('Nêu một ví dụ ưu tiên recall, một ví dụ ưu tiên precision.',),('Vì sao k-NN với k=1 luôn đạt 100% trên tập huấn luyện?',)],
 [('Accuracy = 70/100 = <b>0,7</b>; Precision = 40/50 = <b>0,8</b>; Recall = 40/60 ≈ <b>0,667</b>.',),('Accuracy 98%, nhưng mô hình không phát hiện thư rác nào (recall = 0): <b>không đáng tin</b>.',),('Chọn <b>B</b>: A quá khớp (chênh 29%), B tổng quát hoá tốt.',),('(a) <b>Sai</b> (dùng tập kiểm định). (b) <b>Đúng</b>. (c) <b>Sai</b> (do quá đơn giản). (d) <b>Đúng</b>.',),('Recall: tầm soát bệnh; precision: lọc thư rác.',),('Mỗi điểm huấn luyện có chính nó là láng giềng gần nhất (khoảng cách 0).',)],hper=2)
